```cpp
#include <sstream>
#include <string>
#include <iomanip>
#include <domdocument>

std::string htmlify(const std::string& markdown) {
    std::istringstream iss(markdown);
    std::string line;
    std::string tag;

    // Process each line
    while (iss >> line) {
        if (line.size() > 1 && line[1] == '#') {
            tag = "h1";
            iss.ignore(std::numeric_limits<iosstream>::max(), '\n');
        } else if (line.size() > 1 && line[1] == '//') {
            tag = "h2";
            iss.ignore(std::numeric_limits<iosstream>::max(), '\n');
        } else if (line.size() > 1 && line[1] == 'p') {
            tag = "p";
            iss.ignore(std::numeric_limits<iosstream>::max(), '\n');
        } else {
            tag = line;
        }

        // HTML tag creation
        switch(tag) {
            case "h1":
                return "<h1>" + std::to_string(line) + "</h1>";
            case "h2":
                return "<h2>" + std::to_string(line) + "</h2>";
            case "p":
                return "<p>" + line + "</p>";
            default:
                throw std::invalid_argument("Unknown markdown tag.");
        }
    }

    // Handle empty strings
    if (!iss.eof()) {
        return tag + std::string("") + "." + line;
    }

    return tag;
}

// Example usage:
std::string markdown_text = "This is a sample markdown string. It contains a header: h1 and a paragraph: p.</p>";
std::string html_text = htmlify(markdown_text);
std::cout << html_text << std::endl; // Output: <h1>This is a sample markdown string.</h1><p>This is a paragraph.</p>

// This function assumes that lines beginning with '#' are headers and lines beginning with '//' are comments. You may need to modify it based on your specific markdown format.
```

This function takes a string containing markdown text and returns a string containing the HTML version of the markdown. The function uses a `std::istringstream` to parse the markdown into lines, then uses a switch statement to transform the markdown into HTML tags and content.

